'''Minimal JSON-like encoder inspired by tickets in serialization libs.'''


def dumps_string(s):
    '''Encode a Python string for inclusion as a JSON string literal.

    BUG: forgets to escape backslashes.
    '''
    out = ['"']
    for ch in s:
        if ch == '"':
            out.append('\\"')
        elif ord(ch) < 0x20:
            out.append('\\u%04x' % ord(ch))
        else:
            out.append(ch)
    out.append('"')
    return ''.join(out)

