'''Itinerary helper inspired by tickets in itertools-style libs.'''


def join_unique(parts, sep=', '):
    '''Join unique items, preserving original order.

    BUG: when input is a generator, consumes it twice -> empty output.
    '''
    seen = set()
    for p in parts:
        seen.add(p)
    out = []
    for p in parts:
        if p in seen:
            out.append(p)
            seen.remove(p)
    return sep.join(out)

