'''Tiny flag parser inspired by CLI bug reports.'''


def parse_flags(argv):
    '''Parse ``--key=value`` and ``--flag`` pairs into a dict.

    BUG: ``--key value`` (space-separated) is ignored.
    '''
    out = {}
    for a in argv:
        if a.startswith('--') and '=' in a:
            k, _, v = a[2:].partition('=')
            out[k] = v
        elif a.startswith('--'):
            out[a[2:]] = True
    return out

